// MCP tools for batch 51 (1-Nov-2026): industrial design & 3D printing.
// Pure cores come from src/tools_core51.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/*) — one source of truth
// with the /tools/ pages (image/svg/text-to-stl, stl-viewer, 3d-print-cost-calculator, 3d-print-tolerance, box/enclosure/gear
// generators, screw-size-chart, tap-drill-chart, hand-size-chart). Stateless: no D1/R2, no fetch, no WASM.
import * as C from "./tools_core51.js";

const { MGDMesh, MGDPart } = C;
const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => (structuredContent ? { content: [{ type: "text", text }], structuredContent } : { content: [{ type: "text", text }] });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const num = (x, d, lo, hi) => { const n = Number(x); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : d; };
const int = (x, d, lo, hi) => { const n = parseInt(x, 10); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : d; };
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const fence = (lang, s) => "```" + lang + "\n" + String(s).replace(/\n$/, "") + "\n```";
const r2 = (x) => Math.round(x * 100) / 100;
const STL_TEXT_CAP = 200 * 1024;    // ASCII STL returned inline
const B64_OUT_CAP = 400 * 1024;     // base64 STL/3MF returned inline
const B64_IN_CAP = 4 * 1024 * 1024; // base64 input accepted by analyze_3d_model
const MAX_VERTS = 20000;
const STEP_TEXT_CAP = 300 * 1024; // STEP (faceted B-rep, text) returned inline            // 2D outline vertices accepted by make_extruded_part

export const TOOL_DEFS = [];
const HANDLERS = {};
export const NEXT51 = {};
function def(d, handler, next) { TOOL_DEFS.push(d); HANDLERS[d.name] = handler; NEXT51[d.name] = next; }

// ---- shared helpers ---------------------------------------------------------------------------------------------------
function ringFrom(a) { // [[x,y],...] or [x,y,x,y...] or [{x,y}]
  if (!Array.isArray(a)) return null;
  if (a.length && typeof a[0] === "number") { const o = []; for (let i = 0; i + 1 < a.length; i += 2) o.push([+a[i], +a[i + 1]]); return o; }
  return a.map((p) => (Array.isArray(p) ? [+p[0], +p[1]] : p && typeof p === "object" ? [+p.x, +p.y] : [NaN, NaN]));
}
function countVerts(mp) { let n = 0; mp.forEach((p) => p.forEach((r) => (n += r.length))); return n; }
function fileOut(parts, mesh, format, base) {
  const out = {};
  if (format === "none") return out;
  if (format === "step") {
    if (!C.MGDStep) { out.too_big = "STEP export is not available on this server."; return out; }
    let r; try { r = C.MGDStep.toSTEP(parts.map((p) => ({ mesh: p.mesh, name: p.name })), { name: base }); } catch (e) { out.too_big = "STEP export failed: " + str(e && e.message, 200); return out; }
    if (r.step.length > STEP_TEXT_CAP) out.too_big = `The STEP file is ${Math.round(r.step.length / 1024)} KB: too big to return inline. Use stl_base64 / 3mf_base64, or download STEP from the page.`;
    else { out.step = r.step; out.filename = base + ".step"; out.mime = "model/step"; out.step_stats = r.stats; }
    return out;
  }
  if (format === "stl_base64" || format === "3mf_base64") {
    const bytes = format === "3mf_base64" ? MGDMesh.to3MF(parts.map((p) => ({ mesh: p.mesh, name: p.name })), { title: base }) : MGDMesh.toSTL(mesh, base);
    const b64 = MGDMesh.toBase64(bytes);
    if (b64.length > B64_OUT_CAP) out.too_big = `The ${format === "3mf_base64" ? "3MF" : "STL"} is ${Math.round(bytes.length / 1024)} KB: too big to return inline. Simplify the outline or make it in the browser.`;
    else { out.base64 = b64; out.bytes = bytes.length; out.filename = base + (format === "3mf_base64" ? ".3mf" : ".stl"); out.mime = format === "3mf_base64" ? "model/3mf" : "model/stl"; }
    return out;
  }
  const txt = MGDMesh.toSTLAscii(mesh, base);
  if (txt.length > STL_TEXT_CAP) out.too_big = `The ASCII STL is ${Math.round(txt.length / 1024)} KB: too big to return inline. Ask for format="stl_base64" (binary, ~5x smaller) or simplify the outline.`;
  else { out.stl = txt; out.filename = base + ".stl"; }
  return out;
}

// ---- make_extruded_part -----------------------------------------------------------------------------------------------
def({
  name: "make_extruded_part",
  description: "Use when a flat 2D outline (an SVG path or file, a polygon with holes, or simple shapes) must become a 3D-printable part: extrudes it to a thickness in millimetres and returns a watertight STL (ASCII text or base64) or 3MF (base64), with dimensions, volume, a minimum-wall check and an SVG preview of the profile. Styles: flat part, raised on a base plate, engraved into a plate, or keychain (outline border + ring). Features: scale to a width/height, through holes, keyring/finger loops fused to the outline, separate pins with clearance, rounded corners, mirror. Same engine as the free web tools image-to-stl / svg-to-stl / text-to-stl. 2.5D only (constant-thickness profiles); it does not turn photos into full 3D models.",
  inputSchema: {
    type: "object",
    properties: {
      svg: { type: "string", description: "SVG markup (filled shapes; units from width/height/viewBox) or a bare path 'd' string. Strokes are ignored unless stroke_width is set." },
      polygons: { type: "array", description: "Alternative to svg: polygons in mm, each [outer ring, hole ring, ...], ring = [[x,y],...] (y up). A single ring is also accepted.", items: { type: "array" } },
      fill_rule: { type: "string", enum: ["nonzero", "evenodd"], description: "For polygons: how nested rings fill (default evenodd)." },
      width_mm: { type: "number", description: "Scale the outline uniformly to this width in mm (or use height_mm). Default: keep the input size (SVG units / polygon mm)." },
      height_mm: { type: "number" },
      thickness_mm: { type: "number", description: "Part thickness (flat) or raised height (raised/keychain). Default 3." },
      style: { type: "string", enum: ["flat", "raised", "engraved", "keychain"], description: "flat (default) = the outline is the part; raised = outline on a base plate; engraved = outline cut into a plate; keychain = raised + outline border + ring." },
      base_thickness_mm: { type: "number", description: "Plate thickness for raised/engraved/keychain (default 2)." },
      base_padding_mm: { type: "number", description: "Plate margin around the outline (default 3)." },
      base_shape: { type: "string", enum: ["outline", "roundrect", "rect", "circle"] },
      engrave_depth_mm: { type: "number", description: "Engraved style depth (default 1)." },
      holes: { type: "array", items: { type: "object", properties: { x: { type: "number" }, y: { type: "number" }, d: { type: "number" }, pin: { type: "boolean" }, clearance: { type: "number" } } }, description: "Through holes in mm, measured from the lower-left corner of the scaled outline. pin=true adds clearance (default 0.3 mm) for a printed pin." },
      loop: { type: "object", properties: { d_inner: { type: "number" }, wall: { type: "number" }, side: { type: "string", enum: ["left", "right", "top", "bottom"] } }, description: "Keyring/lanyard ring fused to the outline." },
      loops: { type: "array", items: { type: "object", properties: { x: { type: "number" }, y: { type: "number" }, d_inner: { type: "number" }, wall: { type: "number" } } }, description: "Extra rings (e.g. finger loops on a handle) fused to the outline, centre x/y in mm." },
      pins: { type: "array", items: { type: "object", properties: { d: { type: "number" }, length: { type: "number" } } }, description: "Separate cylindrical pins printed beside the part (e.g. a pivot pin through matching holes)." },
      fillet_mm: { type: "number", description: "Round the outline's corners (convex and concave) by this radius." },
      min_wall_mm: { type: "number", description: "Warn where the outline is narrower than this (default 1.2 mm = 3 perimeters of a 0.4 mm nozzle)." },
      mirror: { type: "boolean" },
      format: { type: "string", enum: ["stl_ascii", "stl_base64", "3mf_base64", "step", "none"], description: "Output file. step = faceted STEP AP214 solid for CAD (text, capped at 300 KB; curves become flat facets). stl_ascii (default, capped at 200 KB), stl_base64 (binary), 3mf_base64 (mm units, one object per part), none (just the report)." },
      name: { type: "string", description: "Part name for the file (default 'part')." },
    },
  },
  annotations: RO("Extrude outline to STL/3MF"),
}, extrudedPart, "Next step: check fits with get_print_clearance (pins/holes), or analyze_3d_model on another file. Users can preview, tweak and download it at https://madegooddesigns.com/tools/svg-to-stl/ or /tools/image-to-stl/.");

function extrudedPart(a) {
  let mp = null, srcNote = "", warn = [];
  if (a.svg != null && str(a.svg, 10).trim()) {
    const S = C.MGDSvgShape;
    if (!S) return err("SVG input is not available on this server yet; pass polygons (mm) instead.");
    const svgIn = str(a.svg, 2000000).trim();
    if (/^\s*</.test(svgIn)) {
      let r;
      try { r = S.parse(svgIn, { tol: 0.02 }); } catch (e) { return err("Could not read the SVG: " + str(e && e.message, 200)); }
      if (!r || r.ok === false) return err("Could not read the SVG: " + str(r && (r.error || (r.warnings || []).join(" ")), 300));
      const layers = (r.layers || []).filter((l) => l.mp && l.mp.length);
      mp = r.union && r.union.length ? r.union : layers.reduce((acc, l) => MGDMesh.union(acc, l.mp), []);
      (r.warnings || []).forEach((w) => warn.push(w));
      if (r.security && r.security.length) warn.push("Ignored for safety: " + r.security.slice(0, 5).join("; ") + ".");
      srcNote = `SVG (${layers.length} fill colour${layers.length === 1 ? "" : "s"} merged; ${r2(r.width_mm || 0)} × ${r2(r.height_mm || 0)} mm canvas)`;
    } else {
      let rings;
      try { rings = S.pathToRings(svgIn.replace(/^d\s*=\s*["']?|["']$/g, ""), 0.02); } catch (e) { return err("Could not read the path data: " + str(e && e.message, 200)); }
      mp = MGDMesh.nest(rings || [], a.fill_rule === "evenodd" ? "evenodd" : "nonzero");
      srcNote = `SVG path data (${(rings || []).length} subpath(s), read as mm)`;
    }
  } else if (Array.isArray(a.polygons) && a.polygons.length) {
    const depth = (x) => (Array.isArray(x) ? 1 + depth(x[0]) : x && typeof x === "object" ? 1 : 0); // point=1, ring=2, polygon=3, list=4
    const d0 = depth(a.polygons), polys = d0 === 2 ? [[a.polygons]] : d0 === 3 ? [a.polygons] : a.polygons;
    const rings = [];
    polys.slice(0, 500).forEach((poly) => (Array.isArray(poly) ? poly : []).forEach((r) => { const q = ringFrom(r); if (q && q.length >= 3 && q.every((v) => Number.isFinite(v[0]) && Number.isFinite(v[1]))) rings.push(q); }));
    if (!rings.length) return err("polygons must be [[outer ring, hole ring...], ...] with rings of at least 3 [x, y] points in mm.");
    mp = MGDMesh.nest(rings, a.fill_rule === "nonzero" ? "nonzero" : "evenodd");
    srcNote = `${rings.length} ring(s) in mm`;
  } else return err("Pass svg (markup or a path d string) or polygons ([[outer, holes...], ...] in mm). Example: polygons=[[[[0,0],[60,0],[60,15],[0,15]]]], thickness_mm=3, holes=[{x:8,y:7.5,d:4}].");
  if (!mp || !mp.length) return err("The outline is empty after filling (open paths or strokes only?). Close the shapes or pass filled polygons.");
  if (countVerts(mp) > MAX_VERTS) return err(`The outline has ${countVerts(mp)} points (limit ${MAX_VERTS}). Simplify it, or use the web tool ${T}/svg-to-stl/.`);
  const o = {
    style: ["flat", "raised", "engraved", "keychain"].includes(a.style) ? a.style : "flat",
    thickness: num(a.thickness_mm, 3, 0.2, 300),
    base: { thickness: num(a.base_thickness_mm, 2, 0.2, 100), padding: num(a.base_padding_mm, 3, 0, 100), shape: ["outline", "roundrect", "rect", "circle"].includes(a.base_shape) ? a.base_shape : undefined },
    depth: num(a.engrave_depth_mm, 1, 0.2, 50),
    width: a.width_mm != null ? num(a.width_mm, 0, 1, 2000) : undefined,
    height: a.width_mm == null && a.height_mm != null ? num(a.height_mm, 0, 1, 2000) : undefined,
    holes: (Array.isArray(a.holes) ? a.holes : []).slice(0, 100),
    loop: a.loop && typeof a.loop === "object" ? a.loop : undefined,
    loops: (Array.isArray(a.loops) ? a.loops : []).slice(0, 20),
    pins: (Array.isArray(a.pins) ? a.pins : []).slice(0, 20),
    fillet: a.fillet_mm > 0 ? { outer: num(a.fillet_mm, 0, 0, 50), inner: num(a.fillet_mm, 0, 0, 50) } : undefined,
    minWall: num(a.min_wall_mm, 1.2, 0.1, 20),
    mirror: !!a.mirror,
  };
  let r;
  try { r = MGDPart.build(mp, o); } catch (e) { return err("Could not build the part: " + str(e && e.message, 200)); }
  if (!r || !r.mesh || !r.mesh.tri.length) return err("Could not build the part: " + str(r && r.error, 200));
  const an = r.analysis, main = r.parts.length > 1 ? MGDMesh.analyze(r.parts[0].mesh) : an, base = (str(a.name, 40).replace(/[^\w-]+/g, "-").replace(/^-+|-+$/g, "") || "part") + `-${r2(main.size[0])}x${r2(main.size[1])}x${r2(main.size[2])}mm`;
  const file = fileOut(r.parts, r.mesh, ["stl_ascii", "stl_base64", "3mf_base64", "step", "none"].includes(a.format) ? a.format : "stl_ascii", base);
  warn = warn.concat(r.warnings || []);
  const lines = [
    `**${o.style} part from ${srcNote}**: ${r2(main.size[0])} × ${r2(main.size[1])} × ${r2(main.size[2])} mm${r.parts.length > 1 ? ` (with pins laid out beside it: ${r2(an.size[0])} × ${r2(an.size[1])} × ${r2(an.size[2])} mm overall)` : ""}, total volume ${r2(an.volume / 1000)} cm³ (≈ ${r2(an.volume / 1000 * 1.24)} g of solid PLA at 1.24 g/cm³), ${an.triangles} triangles, ${r.parts.length} part(s)${r.parts.length > 1 ? " (" + r.parts.map((p) => p.name).join(", ") + ")" : ""}.`,
    an.watertight ? "Mesh check: watertight and manifold (every edge shared by exactly two triangles, consistent winding), units mm." : `Mesh check FAILED: ${an.boundaryEdges} open edges. Please report this outline.`,
    r.thin && !r.thin.ok ? `Minimum wall: areas narrower than ${o.minWall} mm (${r2(r.thin.area)} mm², red in the preview) may print weak.` : `Minimum wall: no area narrower than ${o.minWall} mm.`,
  ];
  if (r.scale && r.scale !== 1) lines.push(`Scaled ×${r2(r.scale)} to fit the requested size.`);
  if (warn.length) lines.push("Notes: " + warn.join(" "));
  lines.push("Profile preview (SVG, mm):\n" + fence("svg", r.svg));
  if (file.stl) lines.push(`${file.filename} (ASCII STL, mm):\n` + fence("stl", file.stl));
  else if (file.step) lines.push(`${file.filename} (STEP AP214, mm, ${file.step_stats.solids} solid(s) of ${file.step_stats.faces} flat faces; curves are faceted):\n` + fence("step", file.step));
  else if (file.base64) lines.push(`${file.filename}: ${file.bytes} bytes, base64 in structuredContent.file.base64 (${file.mime}). Decode and save it to print.`);
  else if (file.too_big) lines.push(file.too_big);
  lines.push(`Edit, preview in 3D and download in the browser: ${T}/svg-to-stl/ (vector) or ${T}/image-to-stl/ (images).`);
  return ok(lines.join("\n\n"), { dims_mm: { w: r2(main.size[0]), h: r2(main.size[1]), t: r2(main.size[2]) }, overall_mm: { w: r2(an.size[0]), h: r2(an.size[1]), t: r2(an.size[2]) }, volume_mm3: an.volume, area_mm2: an.area, triangles: an.triangles, parts: r.parts.map((p) => p.name), watertight: an.watertight, thin: { ok: r.thin ? r.thin.ok : true, area_mm2: r.thin ? r.thin.area : 0 }, warnings: warn, svg_preview: r.svg, file });
}


// ---- analyze_3d_model -------------------------------------------------------------------------------------------------
const UNITS = { mm: 1, cm: 10, in: 25.4, m: 1000 };
def({
  name: "analyze_3d_model",
  description: "Use when you have a 3D-print file (STL, OBJ or 3MF) and need its real size, volume, surface area, triangle count, number of shells and whether it is watertight/manifold (open, non-manifold or flipped edges), plus an ESTIMATED filament weight, length and print cost for a material (PLA, PETG, ABS, ASA, TPU, nylon, resin; densities from manufacturer data sheets, cited). Pass ASCII STL or OBJ text in model_text, or any STL/OBJ/3MF as base64 in file_base64 (max ~3 MB). 3MF units are read from the file; STL/OBJ are assumed mm unless units says otherwise. Weight is a shell + infill estimate, not a slicer result.",
  inputSchema: {
    type: "object",
    properties: {
      model_text: { type: "string", description: "ASCII STL ('solid … facet …') or OBJ text." },
      file_base64: { type: "string", description: "Binary STL, ASCII STL, OBJ or 3MF file, base64-encoded (≤ 4 MB of base64)." },
      filename: { type: "string", description: "Helps detect the format (e.g. part.3mf)." },
      units: { type: "string", enum: ["mm", "cm", "in", "m"], description: "Units of an STL/OBJ (default mm). Ignored for 3MF (the file says)." },
      material: { type: "string", enum: ["pla", "petg", "abs", "asa", "tpu", "nylon", "resin"], description: "Material for the weight estimate (default pla)." },
      infill_percent: { type: "number", description: "Infill % (default 15)." },
      walls: { type: "integer", description: "Perimeters (default 2, 0.45 mm line width)." },
      price_per_kg: { type: "number", description: "Filament price per kg (or per litre for resin) to also return a cost estimate." },
      print_hours: { type: "number", description: "Print time from your slicer, for electricity and machine wear in the cost." },
      printer_watts: { type: "number", description: "Average printer power (default 100 W)." },
      tariff_per_kwh: { type: "number", description: "Electricity price per kWh (default 0.15)." },
    },
  },
  annotations: RO("Analyze 3D model (STL/OBJ/3MF)"),
}, analyzeModel, "Next step: if it is not watertight, re-export from the CAD app; to price a batch with labour and markup use https://madegooddesigns.com/tools/3d-print-cost-calculator/; view and measure it at https://madegooddesigns.com/tools/stl-viewer/; check fits with get_print_clearance.");

async function analyzeModel(a) {
  let bytes = null, name = str(a.filename, 120);
  if (a.file_base64 != null && str(a.file_base64, 10)) {
    const b = String(a.file_base64).replace(/^data:[^,]*,/, "");
    if (b.length > B64_IN_CAP) return err(`file_base64 is ${Math.round(b.length / 1024)} KB; the limit is ${B64_IN_CAP / 1024 / 1024} MB of base64. Use the browser tool ${T}/stl-viewer/ for big files (nothing is uploaded there).`);
    bytes = MGDMesh.fromBase64(b);
  } else if (a.model_text != null && str(a.model_text, 10)) {
    const t = str(a.model_text, B64_IN_CAP);
    bytes = new TextEncoder().encode(t);
    if (!name) name = /^\s*solid/i.test(t) ? "model.stl" : "model.obj";
  } else return err("Pass model_text (ASCII STL or OBJ) or file_base64 (STL/OBJ/3MF) plus an optional filename.");
  let r;
  try { r = await MGDMesh.parseAny(bytes, name); } catch (e) { return err("Could not read the model: " + str(e && e.message, 200)); }
  let mesh = r.mesh, scale = 1, unitNote = "";
  if (r.format === "3mf") unitNote = `3MF unit: ${r.unit} (converted to mm)`;
  else { scale = UNITS[a.units] || 1; unitNote = `${r.format.toUpperCase()} has no units: read as ${a.units && UNITS[a.units] ? a.units : "mm"}`; if (scale !== 1) mesh = MGDMesh.scale(mesh, scale); }
  if (mesh.tri.length / 3 > 3000000) return err("More than 3 million triangles: too large to analyse here. Use the browser viewer.");
  const an = MGDMesh.analyze(mesh);
  const out = { format: r.format, unit_note: unitNote, size_mm: an.size.map(r2), bbox_mm: { min: an.bbox.min.map(r2), max: an.bbox.max.map(r2) }, volume_cm3: r2(an.volume / 1000), area_cm2: r2(an.area / 100), triangles: an.triangles, shells: an.shells, watertight: an.watertight, open_edges: an.boundaryEdges, non_manifold_edges: an.nonManifoldEdges, flipped_edges: an.inconsistentEdges, inside_out: an.insideOut };
  const lines = [`**${r.format.toUpperCase()} model**: ${out.size_mm.join(" × ")} mm (${unitNote}), volume ${out.volume_cm3} cm³, surface ${out.area_cm2} cm², ${an.triangles} triangles, ${an.shells} shell(s).`,
    an.watertight ? (an.insideOut ? "Mesh check: closed but INSIDE OUT (normals point inward): flip normals before slicing." : "Mesh check: watertight and manifold.") : `Mesh check: NOT watertight: ${an.boundaryEdges} open edges, ${an.nonManifoldEdges} non-manifold edges, ${an.inconsistentEdges} flipped edges. Volume and weight below are unreliable until it is repaired.`];
  if (Math.max(...an.size) < 5 && r.format !== "3mf" && (!a.units || a.units === "mm")) lines.push("The model is under 5 mm: it may be in inches or centimetres. Re-run with units='in' or 'cm' if so.");
  const P = C.MGDPrint3D;
  if (P && an.volume > 0) {
    const st = P.meshStats(mesh);
    const mat = P.MATERIALS[a.material] ? a.material : "pla";
    const est = P.estimate({ volume_mm3: st.volume_mm3, area_flat_mm2: st.area_flat_mm2, area_side_mm2: st.area_side_mm2, infill: num(a.infill_percent, 15, 0, 100), walls: int(a.walls, 2, 0, 20), material: mat });
    const m = P.MATERIALS[mat];
    out.estimate = { material: mat, density_g_cm3: m.density, grams: r2(est.grams), meters: est.meters != null ? r2(est.meters) : null, ml: est.ml != null ? r2(est.ml) : null, infill_percent: num(a.infill_percent, 15, 0, 100), walls: int(a.walls, 2, 0, 20), model: est.model, source: m.source + " " + m.url };
    lines.push(`Estimated ${m.name}: ${r2(est.grams)} g${est.meters != null ? ` (${r2(est.meters)} m of 1.75 mm filament)` : ""}${est.ml != null ? `, ${r2(est.ml)} ml resin` : ""} at ${out.estimate.infill_percent}% infill and ${out.estimate.walls} walls; density ${m.density} g/cm³ (${m.source}). Solid weight would be ${r2(est.solid_grams)} g. This is an estimate, not a slicer result.`);
    if (a.price_per_kg != null) {
      const c = P.cost({ estimate: est, price_per_kg: num(a.price_per_kg, 20, 0, 100000), price_per_l: num(a.price_per_kg, 20, 0, 100000), hours: num(a.print_hours, 0, 0, 10000), watts: num(a.printer_watts, 100, 0, 5000), tariff: num(a.tariff_per_kwh, 0.15, 0, 100), quantity: 1 });
      out.cost = c.per_part;
      lines.push(`Cost per part (material${a.print_hours ? " + electricity" : ""}${c.per_part.wear ? " + wear" : ""}): ${r2(c.per_part.total)} (material ${r2(c.per_part.material)}${a.print_hours ? `, electricity ${r2(c.per_part.electricity)}` : ""}). Add labour, failures and markup in ${T}/3d-print-cost-calculator/.`);
    }
  }
  lines.push(`View, measure and convert it privately in the browser: ${T}/stl-viewer/`);
  return ok(lines.join("\n\n"), out);
}

// ---- get_print_clearance ------------------------------------------------------------------------------------------------
def({
  name: "get_print_clearance",
  description: "Use when designing 3D-printed parts that fit together (pins in holes, lids, sliding or rotating joints, print-in-place hinges, press fits): returns the clearance gap to design in for FDM, SLA/resin, SLS or MJF and a fit type, with the published sources (printer makers' and print services' design guides, cited with dates). With a nominal size it returns the hole and pin diameters to model, the general dimensional tolerance at that size, and minimum-feature warnings. Where no guide publishes a value (e.g. press fits for FDM) it says so and recommends printing a clearance test coupon.",
  inputSchema: {
    type: "object",
    properties: {
      process: { type: "string", enum: ["fdm", "sla", "sls", "mjf"], description: "Printing process (default fdm)." },
      fit: { type: "string", enum: ["press", "snug", "sliding", "loose"], description: "press = holds by friction; snug = assembled, no movement; sliding = slides/rotates after assembly; loose = print-in-place moving parts. Omit for the whole table." },
      nominal_mm: { type: "number", description: "Nominal diameter/width in mm (e.g. a 5 mm pin) to get hole and pin sizes." },
      basis: { type: "string", enum: ["pin", "hole"], description: "Which size is fixed at nominal (default pin: the hole grows)." },
    },
  },
  annotations: RO("3D-print clearance / fit"),
}, printClearance, "Next step: print a clearance test coupon (https://madegooddesigns.com/tools/3d-print-tolerance/) to calibrate your printer, then make_extruded_part with holes (pin: true, clearance) or make_box_template for enclosures.");

function printClearance(a) {
  const P = C.MGDPrint3D;
  if (!P) return err("Clearance data is not available on this server yet.");
  const proc = P.PROCESSES[a.process] ? a.process : "fdm";
  const srcLine = (list) => list.map((s) => `${s.name} (${s.url}, read ${s.read})`).join("; ");
  if (a.nominal_mm != null && a.fit) {
    const f = P.fit({ nominal: num(a.nominal_mm, 5, 0.1, 5000), fit: a.fit, process: proc, basis: a.basis === "hole" ? "hole" : "pin" });
    if (!f.ok || !f.gap) return ok(`${f.process_name || proc}, ${f.fit_name || a.fit}: ${f.note || "no published clearance."} Print a clearance coupon to find your printer's value: ${T}/3d-print-tolerance/`, { process: proc, fit: a.fit, gap_mm: null, note: f.note, warnings: f.warnings || [] });
    const lines = [`**${f.process_name}, ${f.fit_name}, nominal ${f.nominal} mm (${f.basis} fixed):** gap ${f.gap.lo === f.gap.hi ? f.gap.lo : f.gap.lo + "–" + f.gap.hi} mm per side (using ${f.gap.used}), so hole Ø${r2(f.hole)} mm and pin Ø${r2(f.pin)} mm (${r2(f.diametral)} mm diametral).`, f.note];
    if (f.tolerance && f.tolerance.items && f.tolerance.items.length) lines.push(`General accuracy at ${f.tolerance.size} mm: ±${f.tolerance.lo}–${f.tolerance.hi} mm (` + f.tolerance.items.map((i) => `${i.label} ±${i.tol}`).join(", ") + ").");
    if (f.min_feature && f.min_feature.note) lines.push(f.min_feature.note);
    if (f.warnings && f.warnings.length) lines.push("Warnings: " + f.warnings.join(" "));
    lines.push("Sources: " + srcLine(f.sources || []) + ". Printers vary: confirm with a test coupon.");
    return ok(lines.filter(Boolean).join("\n\n"), { process: proc, fit: f.fit, nominal_mm: f.nominal, basis: f.basis, gap_mm: f.gap, hole_mm: f.hole, pin_mm: f.pin, diametral_mm: f.diametral, tolerance: f.tolerance, warnings: f.warnings, sources: f.sources });
  }
  const rows = P.table(a.process ? proc : undefined).filter((row) => !a.fit || row.fit === a.fit);
  const md = "| process | fit | gap per side (mm) | note |\n|---|---|---|---|\n" + rows.map((row) => `| ${row.process_name} | ${row.fit_name} | ${row.gap_lo == null ? "not published" : row.gap_lo === row.gap_hi ? row.gap_lo : row.gap_lo + "–" + row.gap_hi} | ${String(row.note || "").replace(/\|/g, "/")} |`).join("\n");
  const srcs = [...new Set(rows.flatMap((row) => row.sources || []))];
  return ok(`Design clearances for 3D-printed fits (gap per side; double it for the diameter):\n\n${md}\n\nSources: ${srcs.join("; ")}. Pass nominal_mm + fit for hole and pin sizes. Calibrate with a coupon: ${T}/3d-print-tolerance/`, { rows });
}

// ---- get_screw_specs ----------------------------------------------------------------------------------------------------
def({
  name: "get_screw_specs",
  description: "Use when a design needs screw, bolt or thread data: ISO metric (M1.6–M30, coarse + fine) and Unified UNC/UNF (#0–1 in) — pitch/TPI, basic pitch and minor diameters, tensile stress area, tap drill (cutting and forming taps, % thread), ISO 273 close/normal/loose clearance holes (inch close/free fit), ISO 4032 nut and ISO 4762 socket-head sizes where verified, and 3D-printing guidance (self-tapping pilot holes, heat-set insert holes, nut traps). Also identifies a screw from a measured diameter (+ pitch/TPI), computes % thread for a given drill, or returns a whole chart. Every value is cited to public sources.",
  inputSchema: {
    type: "object",
    properties: {
      size: { type: "string", description: "e.g. 'M3', 'M8x1', '#6-32', '10-24', '1/4-20', '1/4'." },
      diameter: { type: "number", description: "Measured major diameter, to identify a screw (with unit and optionally pitch_mm or tpi)." },
      unit: { type: "string", enum: ["mm", "in"] },
      pitch_mm: { type: "number" },
      tpi: { type: "number" },
      chart: { type: "string", enum: ["metric", "unified", "drills"], description: "Return a whole chart instead of one size." },
      drill: { type: "string", description: "With size: a drill (mm, inch fraction, number '#7' or letter 'F') to get the % thread it gives." },
      percent: { type: "number", description: "With size: target % thread to get the drill size." },
    },
  },
  annotations: RO("Screw / bolt / thread specs"),
}, (a) => {
  const F = C.MGDFastener; if (!F) return err("Fastener data is not available on this server yet.");
  if (!a.size && a.diameter == null && !a.chart) return err("Pass size (e.g. 'M3', '1/4-20', '#6-32'), or diameter (+ unit, pitch_mm/tpi) to identify a screw, or chart='metric'|'unified'|'drills'.");
  const args = {}; ["size", "diameter", "unit", "pitch_mm", "tpi", "chart", "drill", "percent"].forEach((k) => { if (a[k] != null && a[k] !== "") args[k] = typeof a[k] === "string" ? str(a[k], 40) : a[k]; });
  const r = F.get(args);
  if (!r || r.ok === false || (r.spec && r.spec.ok === false)) { const e = (r && (r.error || (r.spec && r.spec.error))) || "Unknown size."; const cand = (r && (r.candidates || (r.spec && r.spec.candidates))) || []; return err(e + (cand.length ? " Did you mean: " + cand.slice(0, 6).join(", ") + "?" : "")); }
  const src = (r.sources || []).map((x) => `${x.title} (${x.url})`).join("; ");
  return ok(`${r.text}\n\nSources: ${src}\n\nCharts, % thread calculator and printable PDF: ${T}/screw-size-chart/ and ${T}/tap-drill-chart/`, r);
}, "Next step: for 3D-printed parts, get_print_clearance for fits and make_extruded_part / make_box_template with the clearance or insert hole sizes; printable charts at https://madegooddesigns.com/tools/screw-size-chart/.");

// ---- get_hand_anthropometrics -------------------------------------------------------------------------------------------
def({
  name: "get_hand_anthropometrics",
  description: "Use when sizing handles, grips, controls, wearables or adaptive/inclusive products for real hands: returns ANSUR II (2012 US Army Anthropometric Survey, public release; 1,986 women, 4,082 men) hand measurements in mm — hand length, hand breadth, hand circumference, palm length, wrist circumference, thumb-tip reach, grip and forearm-hand lengths — as 1st–99th percentiles, mean and SD by sex, computed from the official data files; the percentile of a given measurement; and grip-design guidance (power/precision grip diameters, handle length, the 19.7%-of-hand-length optimal-diameter rule, built-up handles) from cited ergonomics sources. States the dataset's limits (a military population).",
  inputSchema: {
    type: "object",
    properties: {
      measure: { type: "string", description: "handlength, handbreadth, handcircumference, palmlength, wristcircumference, thumbtipreach, forearmcenterofgriplength, forearmhandlength (aliases accepted). Omit for all." },
      value: { type: "number", description: "With measure: a measurement to place as a percentile." },
      unit: { type: "string", enum: ["mm", "cm", "in"], description: "Unit of value (default mm)." },
      sex: { type: "string", enum: ["female", "male", "both"], description: "Default both." },
      grip: { type: "boolean", description: "Include handle/grip design guidance." },
      hand_length: { type: "number", description: "With grip: a hand length to size the optimal grip diameter for." },
      hand_length_unit: { type: "string", enum: ["mm", "cm", "in"] },
    },
  },
  annotations: RO("Hand anthropometrics (ANSUR II)"),
}, (a) => {
  const A = C.MGDAnthro; if (!A) return err("Anthropometric data is not available on this server yet.");
  const args = {}; ["measure", "value", "unit", "hand_length", "hand_length_unit", "grip"].forEach((k) => { if (a[k] != null && a[k] !== "") args[k] = typeof a[k] === "string" ? str(a[k], 40) : a[k]; });
  if (a.sex === "female" || a.sex === "male") args.sex = a.sex;
  const r = A.get(args);
  if (!r || r.ok === false || r.error || !r.text) return err(((r && r.error) || "Unknown measure.") + " Use one of: " + ((r && r.measures) || ["handlength", "handbreadth", "handcircumference", "palmlength", "wristcircumference", "thumbtipreach"]).join(", ") + ".");
  const src = (r.sources || []).map((x) => `${x.title} (${x.url})`).join("; ");
  const lead = r.percentile && r.percentile.ok ? `**${r.percentile.name} ${r.percentile.value_mm} mm:** ` + Object.entries(r.percentile.results || {}).map(([k, v]) => v.text + ` (5th ${v.p5}, 50th ${v.p50}, 95th ${v.p95} mm)`).join("; ") + ".\n\n" : "";
  return ok(`${lead}${r.text}\n\nLimits: ${r.limitations}\n\nSources: ${src}\n\nFull charts and a measure-your-hand helper: ${T}/hand-size-chart/`, r);
}, "Next step: turn the grip diameter into a printable handle with make_extruded_part (loops/holes in mm), or check fits with get_print_clearance. Charts: https://madegooddesigns.com/tools/hand-size-chart/.");

// ---- make_box_template --------------------------------------------------------------------------------------------------
const SVG_CAP = 200 * 1024;
const capText = (s, what) => (s.length > SVG_CAP ? { too_big: `The ${what} is ${Math.round(s.length / 1024)} KB: too big to return inline. Fewer dividers or a smaller sheet helps, or use the page.` } : null);
const lst = (xs) => (xs && xs.length ? xs.join(" ") : "");
def({
  name: "make_box_template",
  description: "Use when someone needs a box: kind='laser' makes a finger-jointed laser-cut box (closed, open top or lift-off lid, dividers) with kerf compensation as a cut-ready SVG or DXF in mm; kind='enclosure' makes a 3D-printable project box + lid (press-fit lip or screw lid on M2/M2.5/M3 posts with heat-set-insert or self-tap holes, wall cut-outs, PCB standoffs) and returns sizes plus optionally a watertight STL/3MF. Units mm.",
  inputSchema: {
    type: "object",
    properties: {
      kind: { type: "string", enum: ["laser", "enclosure"], description: "Default laser." },
      width: { type: "number", description: "laser: box width (mm). enclosure: inner width." },
      depth: { type: "number", description: "laser: box depth (mm)." },
      height: { type: "number", description: "Height (mm). enclosure: inner cavity height." },
      length: { type: "number", description: "enclosure: inner length (mm)." },
      dims: { type: "string", enum: ["outer", "inner"], description: "laser: whether width/depth/height are outer or inner sizes (default outer)." },
      thickness: { type: "number", description: "laser: sheet thickness (default 3)." },
      kerf: { type: "number", description: "laser: kerf in mm (default 0.2; 0 = off)." },
      finger: { type: "number", description: "laser: target finger width (default 2 x thickness)." },
      style: { type: "string", enum: ["closed", "open", "lid"], description: "laser: default closed." },
      dividers_x: { type: "integer" }, dividers_y: { type: "integer" },
      label: { type: "string", description: "laser: text engraved on the front panel." },
      sheet_width: { type: "number" }, sheet_height: { type: "number" },
      wall: { type: "number", description: "enclosure: wall (default 2)." },
      floor: { type: "number" }, radius: { type: "number", description: "enclosure: outer corner radius." },
      lid: { type: "string", enum: ["lip", "screw", "none"], description: "enclosure: default lip." },
      screw: { type: "string", enum: ["M2", "M2.5", "M3"] },
      screw_mode: { type: "string", enum: ["insert", "selftap"] },
      cutouts: { type: "array", items: { type: "object" }, description: "enclosure: [{face front|back|left|right|bottom|top, shape round|rect|slots, x, z (sides) or y (bottom/top), d | w,h,r | w,h,n,pitch}] in mm from the inner corner." },
      standoffs: { type: "array", items: { type: "object" }, description: "enclosure: [{x, y, h, d, screw}] from the inner front-left corner." },
      format: { type: "string", enum: ["svg", "dxf", "stl_ascii", "stl_base64", "3mf_base64", "step", "none"], description: "laser: svg (default) or dxf. enclosure: none (default, sizes only), stl_base64, 3mf_base64 or step (faceted STEP for CAD, box + lid as two solids, text capped at 300 KB)." },
    },
  },
  annotations: RO("Box template (laser / 3D-print enclosure)"),
}, (a) => {
  const B = C.MGDBox; if (!B) return err("Box maker is not available on this server yet.");
  if (a.kind === "enclosure") {
    const fmt = ["stl_ascii", "stl_base64", "3mf_base64", "step"].includes(a.format) ? a.format : "none";
    const o = { length: num(a.length, 80, 1, 2000), width: num(a.width, 50, 1, 2000), height: num(a.height, 25, 1, 2000), meshes: fmt !== "none" };
    ["wall", "floor", "radius"].forEach((k) => { if (a[k] != null) o[k] = num(a[k], 2, 0, 100); });
    o.lid = { type: ["lip", "screw", "none"].includes(a.lid) ? a.lid : "lip" };
    if (a.screw || a.screw_mode) o.screw = { size: a.screw, mode: a.screw_mode };
    if (Array.isArray(a.cutouts)) o.cutouts = a.cutouts.slice(0, 40);
    if (Array.isArray(a.standoffs)) o.standoffs = a.standoffs.slice(0, 20);
    const r = B.enclosure(o);
    if (!r.ok) return err("Enclosure not possible: " + lst(r.errors));
    const d = r.dims, s = r.screw;
    const lines = [`**Enclosure:** inner ${d.inner.join(" × ")} mm, outer ${d.outer.join(" × ")} mm (wall ${d.wall}, floor ${d.floor}${d.radius ? ", corner radius " + d.radius : ""}); lid ${d.lid.type}${d.lid.size ? " " + d.lid.size.join(" × ") + " mm" : ""}${d.lid.clearance != null ? ", clearance " + d.lid.clearance + " mm" : ""}; assembled ${d.assembled.join(" × ")} mm; usable height ${d.usableHeight} mm; ${d.cutouts} cut-outs, ${d.standoffs} standoffs.`];
    if (s) lines.push(`Screw lid: ${s.size} ${s.mode === "insert" ? "heat-set insert" : "self-tapping"}; clearance hole Ø${s.clearanceHole} mm, post hole Ø${s.postHole} mm × ${s.holeDepth} mm deep, post Ø${s.postDiameter} mm.`);
    if (r.warnings.length) lines.push("Warnings: " + lst(r.warnings));
    const sc = { kind: "enclosure", dims: d, screw: s, warnings: r.warnings };
    if (fmt !== "none") {
      const parts = r.parts.map((p) => ({ name: p.name, mesh: p.mesh }));
      sc.parts = r.parts.map((p) => ({ name: p.name, watertight: p.analysis.watertight, triangles: p.analysis.triangles }));
      const f = fileOut(parts, MGDMesh.merge(...parts.map((p) => p.mesh)), fmt, "enclosure");
      if (f.too_big) f.too_big = f.too_big.replace(/Simplify the outline or make it in the browser\./, "Round cut-outs combined with a screw lid make dense meshes: try format=\"stl_base64\" (smaller), rectangular cut-outs, or build it on the page.");
      Object.assign(sc, f);
      lines.push(f.too_big || `${f.filename} (${f.bytes ? Math.round(f.bytes / 1024) + " KB, " : ""}box and lid side by side, mm, ${f.step ? "two solids; curves are faceted" : "watertight"}) is in structuredContent.`);
      if (f.stl) lines.push(fence("stl", f.stl));
      if (f.step) lines.push(fence("step", f.step));
    }
    lines.push(`Preview, cut-out editor and 3MF: ${T}/enclosure-generator/`);
    return ok(lines.join("\n\n"), sc);
  }
  const o = { width: num(a.width, 120, 1, 5000), depth: num(a.depth, 80, 1, 5000), height: num(a.height, 60, 1, 5000), dims: a.dims === "inner" ? "inner" : "outer", style: a.style };
  ["thickness", "kerf", "finger"].forEach((k) => { if (a[k] != null) o[k] = num(a[k], 0, 0, 100); });
  if (a.dividers_x != null) o.dividersX = int(a.dividers_x, 0, 0, 20);
  if (a.dividers_y != null) o.dividersY = int(a.dividers_y, 0, 0, 20);
  if (a.label) o.label = str(a.label, 40);
  if (a.sheet_width || a.sheet_height) o.sheet = { width: num(a.sheet_width, 600, 50, 3000), height: num(a.sheet_height, 400, 50, 3000) };
  const r = B.laserBox(o);
  if (!r.ok) return err("Box not possible: " + lst(r.errors));
  const d = r.dims, fmt = a.format === "dxf" ? "dxf" : a.format === "none" ? "none" : "svg";
  const lines = [`**Laser-cut box (${d.style}):** outer ${d.outer.join(" × ")} mm, inner ${d.inner.join(" × ")} mm, ${d.thickness} mm sheet, kerf ${d.kerf} mm (each cut moved out by kerf/2). Fingers: width ${d.fingers.width.n} × ${d.fingers.width.f} mm, depth ${d.fingers.depth.n} × ${d.fingers.depth.f} mm, height ${d.fingers.height.n} × ${d.fingers.height.f} mm. ${d.panels} panels on ${d.sheets} sheet(s) of ${d.sheet.join(" × ")} mm${d.dividers.compartments > 1 ? `; ${d.dividers.compartments} compartments of ${d.dividers.compartment.join(" × ")} mm` : ""}.`,
    "Panels (cut size incl. kerf): " + r.panels.map((p) => `${p.name} ${r2(p.w)} × ${r2(p.h)}`).join(", ") + "."];
  if (r.warnings.length) lines.push("Warnings: " + lst(r.warnings));
  const sc = { kind: "laser", dims: d, panels: r.panels.map((p) => ({ name: p.name, w: p.w, h: p.h })), warnings: r.warnings };
  if (fmt !== "none") {
    const body = fmt === "dxf" ? r.dxf : r.svg, big = capText(body, fmt.toUpperCase());
    if (big) { sc.too_big = big.too_big; lines.push(big.too_big); }
    else { sc[fmt] = body; sc.filename = "box-sheet-1." + fmt; lines.push(`Sheet 1 of ${d.sheets} as ${fmt.toUpperCase()} (mm; red hairline = cut, blue = engrave)${d.sheets > 1 ? "; the other sheets are on the page" : ""}:`, fence(fmt === "dxf" ? "text" : "xml", body)); }
  }
  lines.push(`3D fold-up preview, 1:1 and tiled PDFs: ${T}/box-generator/`);
  return ok(lines.join("\n\n"), sc);
}, "Next step: cut a small test box first to check the kerf; for screws and inserts use get_screw_specs, for printed fits get_print_clearance. Pages: https://madegooddesigns.com/tools/box-generator/ and https://madegooddesigns.com/tools/enclosure-generator/.");

// ---- make_gear ----------------------------------------------------------------------------------------------------------
def({
  name: "make_gear",
  description: "Use when someone needs a spur gear or a gear pair: involute profile from module (or diametral pitch), tooth count, pressure angle (20/14.5/25), profile shift, backlash, bore with DIN 6885 keyway and hub; returns all dimensions (pitch/tip/root/base diameters, centre distance, ratio, contact ratio, undercut and interference warnings) and optionally the outline as SVG/DXF in mm or a watertight STL/3MF for printing.",
  inputSchema: {
    type: "object",
    properties: {
      module: { type: "number", description: "Module in mm (default 2). Or pass dp." },
      dp: { type: "number", description: "Diametral pitch (teeth per inch of pitch diameter), instead of module." },
      teeth: { type: "integer", description: "Tooth count (default 20)." },
      teeth2: { type: "integer", description: "Second gear's tooth count: makes a pair (centre distance, ratio, contact ratio)." },
      pressure_angle: { type: "number", enum: [14.5, 20, 25] },
      profile_shift: { type: "number", description: "Profile shift coefficient x (gear 1)." },
      profile_shift2: { type: "number" },
      backlash: { type: "number", description: "mm at the pitch circle (pair: total, split over both gears)." },
      bore: { type: "number", description: "Bore diameter mm (0 = none)." },
      keyway: { type: "string", enum: ["none", "din6885"] },
      hub_diameter: { type: "number" }, hub_height: { type: "number" },
      thickness: { type: "number", description: "Face width mm (for STL/3MF, default 5)." },
      format: { type: "string", enum: ["svg", "dxf", "stl_ascii", "stl_base64", "3mf_base64", "none"], description: "Default none (dimensions only). Pairs return SVG only (both gears in mesh)." },
    },
  },
  annotations: RO("Spur gear generator"),
}, (a) => {
  const G = C.MGDGear; if (!G) return err("Gear maker is not available on this server yet.");
  const o = { teeth: int(a.teeth, 20, 4, 400), pressureAngle: [14.5, 20, 25].includes(+a.pressure_angle) ? +a.pressure_angle : 20 };
  if (a.dp != null) o.dp = num(a.dp, 12, 0.5, 200); else o.module = num(a.module, 2, 0.05, 100);
  if (a.profile_shift != null) o.profileShift = num(a.profile_shift, 0, -1, 2);
  if (a.backlash != null) o.backlash = num(a.backlash, 0, 0, 5);
  if (a.bore) o.bore = num(a.bore, 0, 0, 2000);
  if (a.keyway === "din6885") o.keyway = "din6885";
  if (a.hub_diameter && a.hub_height) o.hub = { d: num(a.hub_diameter, 0, 0, 2000), h: num(a.hub_height, 0, 0, 500) };
  if (a.thickness != null) o.thickness = num(a.thickness, 5, 0.2, 500);
  const fmt = ["svg", "dxf", "stl_ascii", "stl_base64", "3mf_base64"].includes(a.format) ? a.format : "none";
  const dd = (d) => `pitch Ø${d.pitchDiameter}, tip Ø${d.tipDiameter}, root Ø${d.rootDiameter}, base Ø${d.baseDiameter} mm; whole depth ${d.wholeDepth} mm; circular pitch ${d.circularPitch} mm; tooth thickness ${d.toothThickness} mm`;
  if (a.teeth2 != null) {
    const p = G.pair(Object.assign({}, o, { teeth1: o.teeth, teeth2: int(a.teeth2, 40, 4, 400), shift1: o.profileShift || 0, shift2: num(a.profile_shift2, 0, -1, 2) }));
    if (!p.ok) return err("Gear pair not possible: " + lst(p.errors));
    const d = p.dims, warns = [...new Set([...(p.warnings || []), ...(p.gear1.warnings || []), ...(p.gear2.warnings || [])])];
    const lines = [`**Gear pair m${d.module}, ${d.pressureAngle}°, ${d.teeth[0]}:${d.teeth[1]} teeth:** ratio ${d.ratio}, centre distance ${d.centreDistance} mm${d.centreDistance !== d.standardCentreDistance ? ` (standard ${d.standardCentreDistance})` : ""}, contact ratio ${d.contactRatio}${d.interference ? ", INTERFERENCE" : ""}.`,
      `Gear 1: ${dd(p.gear1.dims)}.`, `Gear 2: ${dd(p.gear2.dims)}.`];
    if (warns.length) lines.push("Warnings: " + warns.join(" "));
    const sc = { kind: "pair", dims: d, gear1: p.gear1.dims, gear2: p.gear2.dims, warnings: warns };
    if (fmt === "svg") { const big = capText(p.svg, "SVG"); if (big) lines.push((sc.too_big = big.too_big)); else { sc.svg = p.svg; lines.push("Both gears in mesh, SVG in mm:", fence("xml", p.svg)); } }
    else if (fmt !== "none") lines.push("Files for a pair: call make_gear once per gear (teeth, profile_shift) with the format you need.");
    lines.push(`Meshing animation and downloads: ${T}/gear-generator/`);
    return ok(lines.join("\n\n"), sc);
  }
  const g = G.gear(o);
  if (!g.ok) return err("Gear not possible: " + lst(g.errors));
  const d = g.dims;
  const lines = [`**Spur gear m${d.module} (DP ${d.diametralPitch}), ${d.teeth} teeth, ${d.pressureAngle}°${d.profileShift ? ", shift " + d.profileShift : ""}:** ${dd(d)}; root fillet ${d.rootFillet} mm${d.bore ? `; bore Ø${d.bore.d}${d.bore.keyway ? ` with ${d.bore.keyway.width} × ${d.bore.keyway.depth} mm keyway` : ""} (rim ${d.bore.rim} mm)` : ""}. Fewest teeth without undercut at this angle: ${d.minTeethNoUndercut}.`];
  if (g.warnings.length) lines.push("Warnings: " + lst(g.warnings));
  const sc = { kind: "gear", dims: d, warnings: g.warnings };
  if (fmt === "svg" || fmt === "dxf") {
    const body = fmt === "svg" ? G.gearSVG(g) : G.gearDXF(g), big = capText(body, fmt.toUpperCase());
    if (big) lines.push((sc.too_big = big.too_big)); else { sc[fmt] = body; sc.filename = `gear-m${d.module}-z${d.teeth}.${fmt}`; lines.push(`Outline as ${fmt.toUpperCase()} (mm):`, fence(fmt === "dxf" ? "text" : "xml", body)); }
  } else if (fmt !== "none") {
    const mesh = G.mesh(g, { thickness: o.thickness });
    if (!mesh) return err("Could not build the gear mesh.");
    const base = `gear-m${d.module}-z${d.teeth}`, f = fileOut([{ name: base, mesh }], mesh, fmt, base);
    Object.assign(sc, f);
    lines.push(f.too_big || `${f.filename} (face width ${d.faceWidth || o.thickness || 5} mm, mm units) is in structuredContent.`);
    if (f.stl) lines.push(fence("stl", f.stl));
  }
  lines.push(`Pair calculator, meshing animation and downloads: ${T}/gear-generator/`);
  return ok(lines.join("\n\n"), sc);
}, "Next step: for a mating gear call make_gear with teeth2 to get the centre distance; for printed gears add backlash (and check fits with get_print_clearance). Page: https://madegooddesigns.com/tools/gear-generator/.");

// ---- tool registry ----------------------------------------------------------------------------------------------------
const NAMES = () => new Set(TOOL_DEFS.map((t) => t.name));
export function isTools51Tool(name) { return NAMES().has(name); }
export async function callTools51Tool(name, a) {
  a = a || {};
  const h = HANDLERS[name];
  if (!h) return err("Unknown tool: " + name);
  try { return await h(a); } catch (e) { return err(`${name} failed: ${str(e && e.message, 300)}`); }
}
